            { head: { zh: "命名常量 Named Constant", en: "Named Constant", ms: "Pemalar bernama" }, items: [ { label: { zh: "执行期间内容不可改变", en: "Value cannot change during execution", ms: "Nilai tidak boleh berubah semasa pelaksanaan" } }, { label: { zh: "例：销售税率、圆周率", en: "e.g. sales tax rate, pi", ms: "cth. kadar cukai jualan, pi" } }, { label: { zh: "用 Const 声明", en: "Declared with Const", ms: "Diisytiharkan dengan Const" } }, { label: { zh: "名称用全大写 QUOTA_Integer", en: "Uppercase name: QUOTA_Integer", ms: "Nama huruf besar: QUOTA_Integer" } } ] }
