            { head: { zh: "Decimal", en: "Decimal", ms: "Decimal" }, cells: [ { zh: "精确小数，如金额", en: "Exact decimals such as money", ms: "Perpuluhan tepat seperti wang" } ] },
            { head: { zh: "Double", en: "Double", ms: "Double" }, cells: [ { zh: "14 位精度浮点数", en: "Floating point, 14 digits of accuracy", ms: "Titik terapung, ketepatan 14 digit" } ] },
            { head: { zh: "String", en: "String", ms: "String" }, cells: [ { zh: "字母数字文本", en: "Alphanumeric text", ms: "Teks abjad angka" } ] },
            { head: { zh: "Char", en: "Char", ms: "Char" }, cells: [ { zh: "单个 Unicode 字符", en: "A single Unicode character", ms: "Satu aksara Unicode" } ] }
